from flask import Blueprint
from app.models.problem import Problem

def problem_blueprint():
    blueprint = Blueprint('problem', __name__, url_prefix='/problem')

    @blueprint.route('/', methods=['GET'])
    def get_problems():
        # Logic to fetch and return list of problems (dummy example)
        problems = Problem.query.all()
        return {"problems": [problem.to_dict() for problem in problems]}

    @blueprint.route('/<int:problem_id>', methods=['GET'])
    def get_problem(problem_id):
        # Logic to fetch and return a single problem by ID (dummy example)
        problem = Problem.query.get(problem_id)
        if not problem:
            return {"error": "Problem not found"}, 404
        return problem.to_dict()

    return blueprint

from flask import Blueprint
from app.models.user import User

def user_blueprint():
    user_bp = Blueprint('user', __name__)

    @user_bp.route('/users', methods=['GET'])
    def list_users():
        # This function would list all users
        # Since the database is not specified, returning placeholder data
        users = [{"id": 1, "name": "Alice"}, {"id": 2, "name": "Bob"}]
        return {"users": users}, 200

    @user_bp.route('/users/<int:user_id>', methods=['GET'])
    def get_user(user_id):
        # This function would retrieve user details by ID
        # Placeholder logic due to no database access
        user = {"id": user_id, "name": "Placeholder User"}
        return {"user": user}, 200

    @user_bp.route('/users', methods=['POST'])
    def create_user():
        # This function would create a new user
        # Placeholder logic as database operations are not available
        new_user = {"id": 3, "name": "New User"}
        return {"message": "User created successfully", "user": new_user}, 201

    return user_bp

